class IndependentInputScopeTest {

	@Test
	void provenanceSurvivesCloneAndJavaSerializationThroughWrappers() throws Exception {
		StatementPattern physical = new StatementPattern(Var.of("s"), Var.of("p"), Var.of("o"));
		physical.setIndependentInputScope(true);
		TupleExpr wrapped = new Filter(new Extension(physical), new Bound(Var.of("s")));
		assertTrue(TupleExprs.containsGraphBoundary(wrapped));
		assertTrue(TupleExprs.containsGraphBoundary(wrapped.clone()));
		assertTrue(TupleExprs.containsGraphBoundary(roundtrip(wrapped)));
		assertFalse(physical.isVariableScopeChange(), "Input authority is separate from BIND/FILTER visibility");
		Union visibleScope = new Union(new SingletonSet(), new SingletonSet());
		visibleScope.setVariableScopeChange(true);
		assertFalse(TupleExprs.containsGraphBoundary(visibleScope),
				"A visibility-only UNION flag never manufactures independent graph-input authority");
	}

	@Test
	void absentProvenanceInCurrentAndLegacyStreamsRemainsFalse() throws Exception {
		assertEquals(3006199552086476178L,
				ObjectStreamClass.lookup(AbstractQueryModelNode.class).getSerialVersionUID());
		assertEquals(3887730894113273682L,
				ObjectStreamClass.lookup(StatementPattern.class).getSerialVersionUID());
		assertFalse(roundtrip(new SingletonSet()).isIndependentInputScope());
		// Captured from the actual pre-field model bytecode, not synthesized by serializing the new class with false.
		// AbstractQueryModelNode.class SHA-256: 843bccdc64a9433437b3da604e4bea7557c40efe0bc48ae91960abd922ac3e1a.
		try (var fixture = IndependentInputScopeTest.class.getResourceAsStream("legacy-independent-scope.base64")) {
			assertNotNull(fixture);
			byte[] bytes = Base64.getMimeDecoder()
					.decode(new String(fixture.readAllBytes(), StandardCharsets.US_ASCII));
			try (ObjectInputStream input = new ObjectInputStream(new ByteArrayInputStream(bytes))) {
				StatementPattern legacy = (StatementPattern) input.readObject();
				assertFalse(legacy.isIndependentInputScope());
				assertFalse(legacy.isContextBindingOriginInherited());
				assertEquals(StatementPattern.Scope.NAMED_CONTEXTS, legacy.getScope());
				assertEquals("urn:legacy:graph", legacy.getContextVar().getValue().stringValue());
				for (Var variable : legacy.getVarList()) {
					assertEquals(0, variable.getGraphContextDepth(), "an absent legacy graph depth defaults to zero");
					assertFalse(variable.hasApiInputOrigin(), "an absent legacy API origin defaults to false");
					Var expected = Var.of(variable.getName(), variable.getValue(), variable.isAnonymous(),
							variable.isConstant(), variable.isBNode());
					assertEquals(expected.hashCode(), variable.hashCode(),
							"restored Vars use the current hash algorithm");
					assertEquals(expected, variable);
				}
			}
		}
	}

	@Test
	void selectorOutputProvenanceSurvivesSerializationAndDeclinesBodyCollisions() throws Exception {
		StatementPattern physical = new StatementPattern(StatementPattern.Scope.NAMED_CONTEXTS,
				Var.of("s"), Var.of("p"), Var.of("o"), Var.of("g"));
		assertFalse(physical.isContextBindingOriginInherited());
		physical.setContextBindingOriginInherited(true);
		assertTrue(physical.isContextBindingOriginInherited());
		assertTrue(physical.clone().isContextBindingOriginInherited());
		StatementPattern restored = (StatementPattern) roundtrip(physical);
		assertTrue(restored.isContextBindingOriginInherited());
		restored.replaceChildNode(restored.getObjectVar(), Var.of("g"));
		assertFalse(restored.isContextBindingOriginInherited(),
				"A rewritten body output cannot inherit selector origin");
		StatementPattern constant = physical.clone();
		constant.replaceChildNode(constant.getContextVar(),
				Var.of("g", SimpleValueFactory.getInstance().createIRI("urn:constant"), true, true));
		assertFalse(constant.isContextBindingOriginInherited(), "Constant selectors have no public output binding");
	}

	private static TupleExpr roundtrip(TupleExpr source) throws Exception {
		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		try (ObjectOutputStream output = new ObjectOutputStream(bytes)) {
			output.writeObject(source);
		}
		try (ObjectInputStream input = new ObjectInputStream(new ByteArrayInputStream(bytes.toByteArray()))) {
			return (TupleExpr) input.readObject();
		}
	}
}
